static void *worker(void *arg)
{
    int id = (int)(long)arg;
    long requests = 0, bytes = 0;               /* private to this thread */
    for (long i = 0; i < per_worker; i++) {
        requests++;
        bytes += response_size(id, i);
    }
    pthread_mutex_lock(&stats_lock);            /* one short critical section per thread */
    stats.requests += requests;
    stats.bytes += bytes;
    pthread_mutex_unlock(&stats_lock);
    return NULL;
}
